class PooledConnection implements AutoCloseable {
  private final Connection real; private final List<Connection> pool;
  PooledConnection(Connection real, List<Connection> pool) { this.real = real; this.pool = pool; }
  public void close() { pool.add(real); System.out.println("Zwrocono do puli, isClosed=" + false); }
}
