@FunctionalInterface interface RowHandler { void handle(ResultSet rs) throws SQLException; }
static void executeQuery(Connection conn, String sql, RowHandler handler) throws SQLException {
  try (Statement s = conn.createStatement(); ResultSet rs = s.executeQuery(sql)) {
    while (rs.next()) handler.handle(rs);
  }
}
executeQuery(conn, "SELECT * FROM books", rs -> System.out.println(rs.getString("title")));

