class BookCatalogService {
  private final Connection conn;
  static AtomicInteger opened = new AtomicInteger(), closed = new AtomicInteger();
  BookCatalogService(Connection conn) { this.conn = conn; }
  void insert(String title) throws SQLException {
    try (PreparedStatement ps = conn.prepareStatement("INSERT INTO books (title) VALUES (?)")) { opened.incrementAndGet(); ps.setString(1, title); ps.executeUpdate(); }
    finally { closed.incrementAndGet(); }
  }
  // findById, listAll analogicznie
}
System.out.println("Otwarte: " + BookCatalogService.opened.get() + ", zamkniete: " + BookCatalogService.closed.get());
